<template><div v-if="server" class="max-w-3xl mx-auto p-5 sm:p-8"><h1 class="text-2xl font-bold text-white">Server type</h1><p class="text-dark-400 text-sm mt-1">เลือกชนิดและเวอร์ชัน Minecraft ได้ขณะเซิร์ฟเวอร์หยุดเท่านั้น</p><form class="mt-6 space-y-5" @submit.prevent="save"><section class="panel"><div class="grid sm:grid-cols-2 gap-4"><label class="field">Server type<select v-model="form.type"><option v-for="type in types" :key="type.id" :value="type.id">{{type.label}}</option></select></label><label class="field">Minecraft version<select v-model="form.mc_version" :disabled="loadingVersions"><option value="">{{loadingVersions?'กำลังโหลด…':'เลือกเวอร์ชัน'}}</option><option v-for="version in gameVersions" :key="version" :value="version">{{version}}</option></select></label><label v-if="loaderVersions.length" class="field">Loader version<select v-model="form.loader_version"><option value="">ล่าสุดอัตโนมัติ</option><option v-for="version in loaderVersions" :key="version" :value="version">{{version}}</option></select></label><label v-if="form.type==='curseforge'" class="field sm:col-span-2">CurseForge modpack<select v-model="form.modpack_id" @change="selectModpack"><option value="">เลือก modpack</option><option v-for="pack in rawVersions" :key="pack.slug" :value="pack.slug">{{pack.name}}</option></select><small>ต้องมี CURSEFORGE_API_KEY ใน environment</small></label></div></section><p v-if="error" class="text-red-300 text-sm">{{error}}</p><button class="button primary" :disabled="saving||loadingVersions||!form.mc_version">{{saving?'กำลังบันทึก…':'บันทึก Server type'}}</button></form></div></template>
<script setup lang="ts">definePageMeta({layout:'server'});const route=useRoute(),store=useServersStore(),id=route.params.id as string;const server=computed(()=>store.servers.find(s=>s.id===id));const types=[{id:'vanilla',label:'Vanilla'},{id:'fabric',label:'Fabric'},{id:'forge',label:'Forge'},{id:'neoforge',label:'NeoForge'},{id:'paper',label:'Paper'},{id:'spigot',label:'Spigot'},{id:'bukkit',label:'Bukkit'},{id:'curseforge',label:'CurseForge Modpack'}];const form=reactive<any>({type:'vanilla',mc_version:'',loader_version:'',modpack_id:'',modpack_name:''}),rawVersions=ref<any[]>([]),loadingVersions=ref(false),saving=ref(false),error=ref('');const gameVersions=computed(()=>rawVersions.value.map(v=>typeof v==='string'?v:v.mcVersion||v.id).filter(Boolean));const loaderVersions=computed(()=>{const found=rawVersions.value.find(v=>(v.mcVersion||v.id)===form.mc_version);return found?.loaderVersions||found?.forgeVersions||(form.type==='neoforge'?rawVersions.value.filter(v=>v.mcVersion===form.mc_version).map(v=>v.version):[])});async function loadVersions(reset=false){loadingVersions.value=true;error.value='';if(reset){form.mc_version='';form.loader_version='';form.modpack_id='';form.modpack_name=''}try{rawVersions.value=await $fetch(`/api/versions/${form.type}`) as any[];if(!gameVersions.value.includes(form.mc_version))form.mc_version=gameVersions.value[0]||''}catch(e:any){error.value=e?.data?.statusMessage||'โหลดเวอร์ชันไม่สำเร็จ'}finally{loadingVersions.value=false}}function selectModpack(){const pack=rawVersions.value.find(p=>p.slug===form.modpack_id);if(pack){form.modpack_name=pack.name;form.mc_version=pack.mcVersion||form.mc_version}}async function save(){saving.value=true;error.value='';try{await store.updateServer(id,form)}catch(e:any){error.value=e?.data?.statusMessage||'บันทึกไม่สำเร็จ'}finally{saving.value=false}}watch(()=>form.type,()=>loadVersions(true));onMounted(async()=>{await store.fetchServer(id);if(server.value)Object.assign(form,server.value);await loadVersions()})</script><style scoped>.panel{@apply rounded-2xl bg-dark-900 border border-dark-700 p-5}.field{@apply flex flex-col gap-1.5 text-sm text-dark-300}.field input,.field select{@apply rounded-lg bg-dark-800 border border-dark-600 px-3 py-2.5 text-white outline-none focus:border-mc-green}.field small{@apply text-xs text-dark-500}.button{@apply rounded-xl px-4 py-2.5 text-sm font-medium disabled:opacity-50}.primary{@apply bg-mc-green hover:bg-green-300 text-dark-950}</style>
